effect.shader:
vec4 fxPortOutput;

vec4 fxPortSample(sampler2D image, vec2 uv) {
    vec4 color = texture2D(image, uv);
    if (color.a > 0.0) color.rgb /= color.a;
    else color.rgb = vec3(0.0);
    return color;
}

void fxPortMain() {
    vec2 uv = clamp(acScreenNorm, 0.0, 1.0);
    vec4 original = fxPortSample(inputImg.texture, uv);
    if (abs(uControl2) < 0.000001) {
        fxPortOutput = clamp(original, 0.0, 1.0);
        return;
    }
    vec2 center = clamp(vec2(0.5) + 0.25 * vec2(uControl3, uControl4),
                        0.0, 1.0);
    float scaleX = exp2(uControl5);
    float scaleY = uControl7 > 0.5 ? exp2(uControl6) : scaleX;
    vec2 offset = (uv - center) / vec2(scaleX, scaleY);
    float radius = length(offset) * 2.0;
    vec2 sourceUv = uv;
    if (radius < 1.0) {
        float angle = 15.0 * clamp(0.5 * uControl2, -1.0, 1.0)
                      * (1.0 - radius)
                      * (1.0 - radius);
        float cs = cos(angle);
        float sn = sin(angle);
        vec2 turned = vec2(cs * offset.x - sn * offset.y,
                           sn * offset.x + cs * offset.y);
        sourceUv = center + turned * vec2(scaleX, scaleY);
    }
    vec4 effected = fxPortSample(inputImg.texture, clamp(sourceUv, 0.0, 1.0));
    fxPortOutput = clamp(mix(original, effected, clamp(uControl1, 0.0, 1.0)),
                         0.0, 1.0);
}

void main() {
    fxPortMain();
    gl_FragColor = vec4(fxPortOutput.rgb * fxPortOutput.a, fxPortOutput.a);
}
